code.content:
// before
You are a helpful assistant. Write a short apology email to {{customer_name}} about {{issue_description}}.

// after
You are a helpful, professional assistant. Write a concise, empathetic apology email to
{{customer_name}} about {{issue_description}}. Keep the tone warm but not overly casual,
and avoid making promises about compensation.

{
  "prompts": [
    { "name": "summarize_ticket_v1", "description": "Summarizes a support ticket, plain text output" },
    { "name": "summarize_ticket_v2", "description": "Summarizes a support ticket, now includes a suggested priority level" }
  ]
}

{
  "name": "draft_apology_email",
  "description": "v3, drafts an apology email to a customer about a specific issue, now with a warmer tone and no compensation promises"
}

{
  "name": "draft_apology_email",
  "description": "v3, drafts an apology email to a customer about a specific issue, now with a warmer tone, and an optional refund mention",
  "arguments": [
    { "name": "customer_name", "description": "The customer's name", "required": true },
    { "name": "issue_description", "description": "What went wrong, in plain language", "required": true },
    { "name": "refund_offered", "description": "Refund amount to mention, omit if no refund is being offered", "required": false }
  ]
}

{
  "name": "summarize_ticket_v2",
  "description": "Summarizes a support ticket, now accepts an optional priority hint",
  "arguments": [
    { "name": "ticket_text", "description": "The full text of the support ticket", "required": true },
    { "name": "priority_hint", "description": "A rough priority level to weight the summary toward, omit if unknown", "required": false }
  ]
}

